// --- Payload shapes --------------------------------------------------------

/**
 * Per-port state machine names (`dashboard.md` §5.1). UPLOADING is a task-spec table transfer
 * (`specs.md`) — exclusive like FLASHING, with the same passthrough auto-resume.
 */
export type PortStateName = "IDLE" | "PASSTHROUGH" | "FLASHING" | "UPLOADING" | "RESETTING" | "IN_SESSION" | "ERROR";

/** One passthrough console line. Debug output, never persisted (§5.4). */
export interface OutputLine {
  /** Sent commands interleave as `tx` (§5.3). */
  dir: "rx" | "tx";
  text: string;
  ts: number;
}

/** A board the out-of-band `arduino-cli board list` poll has seen. */
export interface DetectedBoard {
  hardwareId: string;
  address: string;
  fqbn: string | null;
  /** `null` for a board no box is bound to. */
  boxId: number | null;
}

/**
 * The three bundled-sketch-library states of `tasks.md` §2.4. There is no `not_configured`:
 * sketches ship with the app, so there is nothing to configure and no first-run state to be in.
 */
export type LibraryState = "ok" | "empty" | "damaged";

/**
 * Every non-ok state means a broken or partial INSTALL rather than a wrong setting, which is why
 * the messages point at reinstalling and not at a picker.
 */
export interface SketchLibraryStatus {
  state: LibraryState;
  path: string | null;
  /** Populated when state != "ok". */
  message: string | null;
  /**
   * `override` when $EPHYMERIS_SKETCH_LIBRARY points elsewhere — a developer facility, never
   * reachable from the UI.
   */
  source: "bundled" | "override";
}

export interface SketchEntry {
  category: string;
  name: string;
  path: string;
}

/** Carried in full so a missing sketch is inspectable, not silent. */
export interface SkippedEntry {
  path: string;
  reason: string;
}

/** The full result of a bundled-library scan (`tasks.md` §2.3). */
export interface SketchDiscovery {
  library: SketchLibraryStatus;
  sketches: SketchEntry[];
  skipped: SkippedEntry[];
  /** Drives the "Partial" note (`tasks.md` §2.4). */
  skippedCount: number;
  libraries: string[];
  librariesPath: string | null;
}

export interface BoxBinding {
  box: number;
  /** USB serial number — stable across COM renumbering. */
  hardwareId: string | null;
  label: string;
}

/**
 * The Tauri-side store's schema. The sidecar reads the keys it needs and ignores the rest, so
 * adding a setting is deliberately a non-event.
 */
export interface EphymerisSettings {
  dataDirectory: string | null;
  backupDirectory: string | null;
  arduinoCliPath: string | null;
  /**
   * The hardware utility sketch every idle box is returned to (`settings.md` §8). Null turns the
   * baseline off. Keyed by sketch FOLDER NAME rather than by path, matching `taskDefaults` — the
   * path moved when sketches began shipping with the app, and the name is what a session file
   * already records.
   */
  utilitySketchName: string | null;
  defaultBaud: number;
  boxes: BoxBinding[];
  reducedMotion: boolean;
  /**
   * Zodiac layout id for the box-status constellation; null = the legacy fixed layout. Shell-only
   * — the sidecar ignores it.
   */
  constellation: string | null;
  /** Box number (string key, JSON) → star index in the chosen constellation. Shell-only. */
  constellationSlots: Record<string, number>;
  /** First-run box setup finished or explicitly skipped; gates the Config wizard. Shell-only. */
  boxSetupComplete: boolean;
  /**
   * Sketch folder name → this rig's default task parameters for it, keyed by `metadataKey`
   * (`tasks.md` §6.1). Keyed by NAME, not path: the two lab machines keep their Arduino
   * Directories in different places, and the name is what the session file already records.
   * Shell-only — the frontend merges these under the profile's own defaults and sends the result
   * at `sessions.confirmMapping`, so the sidecar never reads them.
   */
  taskDefaults: Record<string, Record<string, unknown>>;
}

/**
 * What the sidecar believes about one box's baseline firmware. `busy` (the port has another
 * owner) and `held` (a confirmed session mapping owns the rig) are both 'not now' rather than
 * 'not working' — the distinction is the whole reason a restore never fights the user.
 */
export type UtilityBaselineState = "unknown" | "restoring" | "ready" | "busy" | "held" | "unavailable" | "failed";

export interface UtilityBoxState {
  box: number;
  state: UtilityBaselineState;
  /** Why, when the state isn't `ready`. */
  detail: string | null;
  /** This box is currently lit by utility.identify. */
  identifying: boolean;
}

/**
 * The whole baseline picture — one snapshot, shared by the command and the event, so a client
 * never merges two shapes.
 */
export interface UtilityStatus {
  configured: boolean;
  /**
   * Resolved from the name against the bundled library — an install-specific fact, informational
   * only.
   */
  sketchPath: string | null;
  sketchName: string | null;
  /**
   * The configured sketch's profile declares an `identify` pair. False means placement can still
   * run, just without lights.
   */
  canIdentify: boolean;
  /**
   * Restores are suspended because a confirmed session mapping owns the boxes — reflashing then
   * would erase the task sketch.
   */
  held: boolean;
  /**
   * Why the baseline isn't operating at all (unset sketch, a path no longer in the Arduino
   * Directory, a non-utility profile).
   */
  message: string | null;
  boxes: UtilityBoxState[];
}

/**
 * `pending` = directory set but no pass has completed yet — a fresh unreachable network path must
 * not read as healthy for its first 10 s.
 */
export type BackupState = "disabled" | "pending" | "ok" | "failed";

export interface BackupStatus {
  configured: boolean;
  directory: string | null;
  state: BackupState;
  /** Finalized files queued for their one-shot copy. */
  pending: number;
  /** Live .tsv files mirrored each pass. */
  tracking: number;
  /** Copies made this sidecar lifetime. */
  mirroredFiles: number;
  lastSuccessAt: string | null;
  lastError: string | null;
  /** A backup.syncNow walk is running. */
  syncing: boolean;
  intervalSeconds: number;
}

export interface SyncResult {
  copied: number;
  /** Already current — not an error. */
  skipped: number;
  failed: number;
  errors: string[];
  directory: string;
}

export type Sex = "M" | "F" | "unknown";

export interface Group {
  id: string;
  name: string;
  /** Run order for consecutive execution. */
  order: number;
}

export interface Animal {
  id: string;
  name: string;
  /** Exactly one group. */
  groupId: string;
  /** Abstract slot 1–6, never a live port. */
  boxNumber: number | null;
  /**
   * Home-cage number — cagemates share one. A grouping label validated as ≥ 1 and nothing else;
   * null means unassigned.
   */
  cage: number | null;
  sex: Sex | null;
  idNumber: string | null;
  notes: string | null;
}

/**
 * The full record, fetched only when a card is opened. The icon is deliberately absent — derived
 * client-side from `id` (cohorts.md §5).
 */
export interface Cohort {
  id: string;
  name: string;
  /** Resolved once at creation, persisted verbatim (§8). */
  dataFolder: string;
  animals: Animal[];
  /** Always ≥ 1 — a default group always exists. */
  groups: Group[];
  archivedAt: string | null;
  createdAt: string;
  updatedAt: string;
}

/** Enough for the grid and dashboard tile, no per-animal detail. */
export interface CohortSummary {
  id: string;
  name: string;
  animalCount: number;
  groupCount: number;
  /**
   * Distinct box numbers this cohort's animals hold. The one piece of animal detail the summary
   * carries, so the browser grid can flag a cohort whose boxes no longer exist on this machine
   * without fetching every cohort in full.
   */
  assignedBoxes: number[];
  archived: boolean;
  createdAt: string;
  updatedAt: string;
}

export interface CohortPatch {
  name?: string;
  /** Replaced wholesale. */
  animals?: Animal[];
  /** Replaced wholesale. */
  groups?: Group[];
}

export interface ProposedAnimal {
  animalId: string;
  boxNumber: number;
}

export interface ProposedGroup {
  name: string;
  order: number;
  animals: ProposedAnimal[];
}

export interface GroupRejection {
  reason: string;
  /** The minimum viable count, so the user can accept it. */
  minimumGroups: number;
}

/** An Auto-Balance preview. Nothing is written; apply via cohorts.update. */
export interface GroupProposal {
  groups: ProposedGroup[];
  /**
   * Set when the request would break the six-per-group constraint (§7.2) — guidance rather than a
   * failure, so not an error reply.
   */
  rejected: GroupRejection | null;
}

/** Global — shared across cohorts. */
export interface Prefix {
  id: string;
  name: string;
}

export type SessionStatus = "configuring" | "running" | "completed" | "aborted";

export interface GroupRun {
  groupId: string;
  order: number;
  startedAt: string;
  endedAt: string | null;
}

export interface Session {
  id: string;
  cohortId: string;
  prefixId: string;
  prefixName: string;
  /** Free text, not strictly numeric (§10). */
  sessionNumber: string;
  /** ISO `YYYY-MM-DD`. */
  date: string;
  startedAt: string;
  endedAt: string | null;
  status: SessionStatus;
  folderPath: string;
  groupRuns: GroupRun[];
  /**
   * Per-box time limit: the sidecar sends STOP to a box this many minutes after that box's own
   * start. Null means no limit.
   */
  durationMinutes: number | null;
}

export type ConfigFieldType = "int" | "float" | "bool" | "string";

/**
 * One operator-tunable parameter. Everything past `default` is presentation metadata and optional
 * — a profile that declares none renders exactly as it did before these keys existed.
 */
export interface ConfigField {
  /** The `.json`/`.mat` field name the form collects under. */
  metadataKey: string;
  /** The `START` command token (§6.3). */
  wireKey: string;
  label: string;
  type: ConfigFieldType;
  default: unknown;
  /**
   * Section heading the form files this field under. Absent = ungrouped, which is how every
   * pre-existing profile renders.
   */
  group?: string;
  /** Suffix shown after the input, e.g. "ms". */
  unit?: string;
  /** Inclusive bound the form clamps to. */
  min?: number;
  /** Inclusive bound the form clamps to. */
  max?: number;
  /** Stepper increment; presentation only. */
  step?: number;
  /** One-line explanation shown with the field. */
  help?: string;
  /** Collapsed behind a disclosure by default. For fields a session should rarely need to touch. */
  advanced?: boolean;
}

export interface LiveMetric {
  id: string;
  label: string;
  triggerCode: number;
  successCode: number;
  alternateCode: number;
  windowSize: number;
}

/** A scored IN_SESSION task, or a PASSTHROUGH tool (§6.2). */
export type ProfileKind = "behavior" | "utility";

export interface ControlOption {
  label: string;
  command: string;
}

/**
 * One row of a `grid` control — a named piece of hardware with its own commands and its own live
 * state key.
 */
export interface ControlChannel {
  label: string;
  /** Telemetry key whose 0/1 value lights this row's indicator. */
  state?: string;
  /** Command that latches this channel. */
  toggle?: string;
  /** Command that pulses this channel. */
  pulse?: string;
}

/** A utility control rendered in Debug Mode (§6.6); sends over port.send. */
export interface Control {
  id: string;
  label: string;
  type: "button" | "select" | "grid";
  /** `button` controls only. */
  command?: string;
  /** `select` controls only. */
  options?: ControlOption[];
  /**
   * `grid` controls only — one row per channel. Exists because a box has 18 controllable outputs,
   * and 36 flat buttons is not a control surface.
   */
  channels?: ControlChannel[];
}

export interface TelemetryField {
  key: string;
  label: string;
}

/**
 * How to parse a utility sketch's non-persisted STATUS lines out of port.output (§6.6). Parsed
 * client-side — nothing here is stored.
 */
export interface TelemetrySpec {
  match: string;
  fields: TelemetryField[];
}

/**
 * The two commands that make a box announce itself — a trial light, a buzzer, whatever the rig
 * has (`settings.md` §8.3). Declared by the sketch so the app never has to know that a Hart-lab
 * box says `ON LIGHT`.
 */
export interface IdentifySpec {
  on: string;
  off: string;
}

/**
 * Parsed from the sketch's task.json sibling (§6.1); passed through verbatim — the sidecar
 * validates shape but doesn't reinterpret.
 */
export interface TaskProfile {
  taskName: string;
  kind: ProfileKind;
  config: ConfigField[];
  /**
   * code → name, string-keyed to match the authored task.json. Display/debug only — metrics use
   * raw codes.
   */
  strobes: Record<string, string>;
  liveMetrics: LiveMetric[];
  /** Utility profiles only. */
  controls: Control[];
  /**
   * Names older software wrote for this same task, so the archive walk can decode historical runs
   * (`tasks.md` §3.7). Declared, never inferred.
   */
  legacyNames: string[];
  /** Utility profiles only. */
  telemetry?: TelemetrySpec;
  /**
   * Utility profiles only — absent means this sketch can't be asked to point at its own box,
   * which the placement walk degrades around rather than refusing.
   */
  identify?: IdentifySpec;
}

/** One box's session-local mapping + task config (`dashboard.md` §7.3). */
export interface SessionBoxMapping {
  box: number;
  animalId: string;
  sketchPath: string;
  /** Keyed by `metadataKey`, per the Task Profile. */
  config: Record<string, unknown>;
}

/** One box as the runner sees it — the source Mission Control renders (§5). */
export interface SessionBox {
  box: number;
  animalId: string;
  animalName: string;
  sketchName: string;
  sketchPath: string;
  running: boolean;
  /**
   * When this box's current run began; null unless running. What lets a reloaded Mission Control
   * resume its elapsed clocks.
   */
  startedAt: string | null;
}

export interface TelemetryMetric {
  id: string;
  /** P(hit) over the rolling window; null until a trial counts. */
  value: number | null;
  /** Counted (hit-or-miss) trials in the window — a window length, not a trial count. */
  n: number;
}

export interface BoxTelemetry {
  box: number;
  animalId: string;
  metrics: TelemetryMetric[];
}

export interface AnimalEnded {
  box: number;
  animalId: string;
  /** `dashboard.md` §10.4's stop-reason set. */
  stopReason: string;
  filePath: string | null;
}

/** The runner-held session — the same shape a sessions.status reply carries. */
export interface RunnerSession {
  session: Session;
  /** Null only before any mapping was confirmed. */
  groupId: string | null;
  boxes: SessionBox[];
}

/**
 * Everything unfinished, discoverable with no prior knowledge of ids. Also the session.lifecycle
 * payload — one shape, one emitter.
 */
export interface ActiveSessions {
  /**
   * Keyed off the live runner, never a bare DB status query — a 'running' row with no live runner
   * is a crash orphan, not resumable.
   */
  running: RunnerSession | null;
  /** Setup never finished; legitimately resumable into the mapping flow. */
  configuring: Session[];
  /**
   * DB says 'running' but no runner holds them — a crash happened. Surfaced for honesty (the .tsv
   * on disk is the record), never for resume.
   */
  stale: Session[];
}

/** One session, from sessions.list or inside a summary. */
export interface SessionListItem {
  id: string;
  cohortId: string;
  prefixName: string;
  sessionNumber: string;
  date: string;
  startedAt: string;
  endedAt: string | null;
  status: SessionStatus;
  folderPath: string;
  /**
   * 1-based chronological position from (date, startedAt) — never from sessionNumber, which is
   * free text and would sort "10" before "9".
   */
  ordinal: number;
  runCount?: number;
}

/**
 * One session folder found on disk, identified by name alone (`sessions/paths.py`). What the
 * archive can assert without opening a file: identity and date, never runs or animals.
 */
export interface DiskSession {
  cohortId: string;
  cohortName: string;
  prefixName: string;
  sessionNumber: string;
  /** ISO YYYY-MM-DD, parsed from the folder name — legacy spellings normalized. */
  date: string;
  folderPath: string;
  /**
   * True when this machine's database holds a session row for the folder — false for a session
   * another Ephymeris machine wrote into the shared archive.
   */
  recorded: boolean;
}

/** One metric's whole-session result (`data.md` §9.2, §3.5). */
export interface MetricSummary {
  id: string;
  label: string;
  /**
   * Whole-session P(hit) — what every panel plots. `null` means no trials scored, which is a
   * different claim from zero.
   */
  pSession: number | null;
  /**
   * Rolling P at the authored window, for continuity with Mission Control. Not interchangeable
   * with pSession.
   */
  pWindow: number | null;
  counted: number;
  triggered: number;
  excluded: number;
  windowSize: number;
  wilsonLow: number | null;
  wilsonHigh: number | null;
  lowConfidence: boolean;
}

/**
 * What actually happened per trial (`data.md` §9.8). Distinct from the declared metrics, which
 * are reward-*unconditional* — they score a detected poke whether or not the fluid hold cleared.
 */
export interface TrialOutcomes {
  /** Every trial boundary seen — one per odor onset. */
  trials: number;
  /**
   * Odor sampled to completion; the denominator for both accuracies. A trial the animal never
   * engaged with is not evidence about discrimination.
   */
  administered: number;
  /** Fluid actually delivered. */
  rewarded: number;
  /** Correct well reached, released before the hold cleared — the right choice, no drop earned. */
  holdFailed: number;
  wrongWell: number;
  /** Administered, but no well was ever answered. */
  noResponse: number;
  /** Never administered — odor port left early, or never poked. */
  aborted: number;
  /** rewarded / administered. Conservative: a hold failure counts against it. */
  pRewarded: number | null;
  /**
   * (rewarded + holdFailed) / administered — the correct side was chosen whether or not the hold
   * earned the drop. Always ≥ pRewarded; the gap between them is the consummatory hold-failure
   * rate.
   */
  pSide: number | null;
  rewardedLow: number | null;
  rewardedHigh: number | null;
  sideLow: number | null;
  sideHigh: number | null;
}

/**
 * How far each offered trial got before the animal dropped out (`data.md` §9.10). Delimited on
 * the trial light, not on odor onset — the firmware only strobes odor-on after the animal has
 * poked and held, so every other count in a run summary is silently conditioned on engagement and
 * none of them can measure it. A ladder, not a partition: presented >= poked >= odorDelivered by
 * construction.
 */
export interface TrialEngagement {
  /** Every trial the box offered — one per trial light. */
  presented: number;
  /** Of those, the ones the animal poked the odor port on. */
  poked: number;
  /**
   * Of those, the ones that reached odor delivery. Equals TrialOutcomes.trials on a well-formed
   * stream — the same trials counted from the other end.
   */
  odorDelivered: number;
  /**
   * presented - poked. The animal never engaged the odor port (LAZY_RAT), plus at most one window
   * a stop or drop truncated.
   */
  noPoke: number;
  /**
   * poked - odorDelivered. Engaged, then let go before the pre-odor hold cleared, so no odor was
   * ever delivered. Distinct from TrialOutcomes.aborted, which received odor and left during
   * sampling.
   */
  pokeAborted: number;
  /** poked / presented. */
  pEngaged: number | null;
  /** odorDelivered / presented. */
  pDelivered: number | null;
  engagedLow: number | null;
  engagedHigh: number | null;
}

/**
 * TrialOutcomes restricted to one declared condition (`data.md` §3.9), in authored liveMetrics
 * order. Answers 'how many trials of this kind were administered, and how many of those paid
 * out'.
 */
export interface ConditionOutcomes {
  metricId: string;
  label: string;
  /**
   * The code that opens this condition's trials — what splits the tally. Two metrics sharing one
   * legitimately cover the same trials.
   */
  triggerCode: number;
  outcomes: TrialOutcomes;
}

export type RunStatus = "ok" | "no-metrics" | "missing" | "unreadable";

/**
 * How much the decoding can be trusted (§8.2). Three states, not two — `sketch-current` means the
 * profile may have changed since the run.
 */
export type ProfileSource = "snapshot" | "sketch-current" | "unavailable";

export interface RunSummary {
  runId: string;
  sessionId: string;
  animalId: string;
  /** Null for an adopted orphan (§8.1) — a filename carries no box. */
  boxNumber: number | null;
  startedAt: string;
  endedAt: string | null;
  sketchPath: string;
  profileHash: string | null;
  /**
   * Hash of the task parameters this run used (`data.md` §6.9). Comparability is the PAIR with
   * `profileHash` — that one covers the profile declaration, which is identical across every run
   * of a sketch however it was tuned. Null for a run recorded before parameters were
   * operator-set.
   */
  paramsHash: string | null;
  profileSource: ProfileSource;
  /** The file is gone but this is its last known-good summary. */
  stale: boolean;
  status: RunStatus;
  metrics: MetricSummary[];
  /**
   * Accuracy pooled across every metric — the only single number that can tell learning from a
   * side bias (§3.7).
   */
  overall: MetricSummary | null;
  /**
   * Null when the profile declares no reward vocabulary (§3.8) — absent rather than zeroed, since
   * 'this task has no notion of a reward delivery' is not 'this animal earned nothing'.
   */
  outcomes: TrialOutcomes | null;
  /**
   * Empty — not null — whenever `outcomes` is null: there is no separate claim to make about a
   * task that can't express an outcome at all.
   */
  conditions: ConditionOutcomes[];
  /**
   * How many trials the box offered and how far each got (§3.10) — the layer above every other
   * count here. Null when the profile declares no trial light, on the same rule as `outcomes`: a
   * zeroed ladder would read as an animal that never engaged rather than as a task that can't
   * say.
   */
  engagement: TrialEngagement | null;
  totalEvents: number;
  durationMs: number | null;
  stopReason: string | null;
  clean: boolean;
  seed: number | null;
  detail: string | null;
  excludedByDefault: boolean;
}

export interface AnalyticsAnimal {
  id: string;
  name: string;
  groupId: string;
  boxNumber: number | null;
  /** Home-cage number, same field as Animal.cage. */
  cage: number | null;
}

export interface ProfileMetricInfo {
  id: string;
  label: string;
  windowSize: number;
}

/** A comparability set: two runs share axes only if they share a hash (§4.3). */
export interface ProfileGroup {
  hash: string;
  taskName: string | null;
  kind: string | null;
  metrics: ProfileMetricInfo[];
  runCount: number;
}

export interface AnalyticsWarning {
  code: string;
  runId: string;
  message: string;
}

export interface AnalyticsCounts {
  runs: number;
  decoded: number;
  noProfile: number;
  missing: number;
  unreadable: number;
}

/** The whole cohort table in one call; selections filter it client-side. */
export interface AnalyticsSummary {
  cohortId: string;
  sessions: SessionListItem[];
  animals: AnalyticsAnimal[];
  groups: Group[];
  /** Flat, not a matrix — two runs really can share one (animal, session). */
  runs: RunSummary[];
  profileGroups: ProfileGroup[];
  counts: AnalyticsCounts;
  warnings: AnalyticsWarning[];
  minCountedTrials: number;
}

export interface MetricSeries {
  id: string;
  label: string;
  values: number[];
  /**
   * Sample size behind each point — the *window* length, capped at windowSize, not a cumulative
   * count. What a confidence band must use.
   */
  n: number[];
  windowSize: number;
}

/** One sample of the within-session strategy walk (`data.md` §11.1). */
export interface StrategyPoint {
  /**
   * Counted trials resolved across *both* conditions at this sample — the only shared clock the
   * two metrics have.
   */
  trial: number;
  x: number;
  y: number;
  /** The smaller of the two rolling window lengths. */
  n: number;
}

export interface RunSeries {
  runId: string;
  mode: "rolling" | "cumulative";
  metrics: MetricSeries[];
  /**
   * The joint walk through the strategy plane. Always rolling, whatever `mode` is — 'what
   * strategy is running right now' is a rolling question. Empty unless the profile declares
   * exactly two conditions. Cannot be assembled client-side from `metrics`: those are indexed by
   * each metric's own counted trials, which interleave.
   */
  trail: StrategyPoint[];
}

export interface SeriesResult {
  series: RunSeries[];
  warnings: AnalyticsWarning[];
}

export interface RescanOrphan {
  path: string;
  /** Matched by name, never guessed (§8.1). */
  animalId: string | null;
  /**
   * The animal name the *document* carries, reported as written even when it is what failed to
   * match.
   */
  animalName: string | null;
  /**
   * Which recording of the animal `animalId` came from. `filename` means the document's `rat`
   * field matched no animal and the file stem did — an exact match against the roster on a second
   * recording of the same fact, never a guess (§8.1). Null when the run is unattributed.
   */
  animalSource: "document" | "filename" | null;
  date: string | null;
  status: string;
  reason: string | null;
}

export interface RescanResult {
  scanned: number;
  adopted: number;
  /**
   * Extra copies of an already-seen run, skipped. A hand-managed archive often keeps a
   * consolidated copy beside the per-prefix originals; adopting both would double every animal
   * (§8.1).
   */
  duplicates: number;
  orphans: RescanOrphan[];
  cohortId: string;
  dataFolder: string;
  /**
   * The cohort's data folder isn't on disk — an unplugged drive or a re-lettered volume.
   * Distinguishes 'nothing there' from 'nowhere to look'.
   */
  folderMissing: boolean;
}

export interface AnalyticsProgress {
  cohortId: string;
  phase: "reading" | "walking";
  done: number;
  total: number;
}

/** One orphaned write-ahead log the crash-recovery backfill processed. */
export interface RecoveredTsv {
  tsvPath: string;
  /** Null when recovery failed. */
  jsonPath: string | null;
  status: "recovered" | "failed";
  /** Recomputed from the lines actually parsed, never copied from a footer. */
  nEvents: number;
  /**
   * The footer's recorded reason when the .tsv has one (a finalized run whose best-effort .json
   * write failed); 'recovered after crash' for a footer-less log. Null on failure.
   */
  stopReason: string | null;
  /** Why recovery failed, when it did. */
  reason: string | null;
}

export interface RecoverResult {
  /** Orphaned .tsv files found — write-ahead logs with no .json sibling. */
  scanned: number;
  recovered: number;
  failed: number;
  entries: RecoveredTsv[];
  cohortId: string;
  dataFolder: string;
  /** Same distinction as RescanResult's: 'nothing there' vs 'nowhere to look'. */
  folderMissing: boolean;
}

export interface ServerHello {
  protocolVersion: number;
  sidecarVersion: string;
}

export interface PortStateData {
  box: number;
  state: PortStateName;
  prev: PortStateName;
  reason: string;
}

export interface PortOutputData {
  box: number;
  lines: OutputLine[];
}

export interface BoardsPresenceData {
  boards: DetectedBoard[];
}

export interface FlashProgressData {
  box: number;
  phase: "compile" | "upload";
  stream: "stdout" | "stderr";
  text: string;
}

export interface CohortsUpdatedData {
  cohorts: CohortSummary[];
}

export interface PrefixesUpdatedData {
  prefixes: Prefix[];
}

/** Failures with no command to attribute them to (§4). */
export interface SidecarErrorData {
  code: string;
  message: string;
  detail: unknown;
}

/**
 * Where a spec's current bytes come from. `shipped_edited` = a user copy shadowing a bundled spec
 * of the same id.
 */
export type SpecOrigin = "shipped" | "shipped_edited" | "user";

/**
 * A row in the spec list. Built from a cheap parse — never a compile — so `specs.list` stays
 * instant however many specs exist.
 */
export interface SpecEntry {
  specId: string;
  /** meta.label, when the document parses. */
  label: string | null;
  description: string | null;
  origin: SpecOrigin;
  template: string | null;
  templateVersion: number | null;
  /**
   * A shipped_edited spec whose BUNDLED bytes moved since the user's copy was made — i.e. an app
   * update changed the shipped version underneath a local edit. Never merged automatically; the
   * user chooses Keep mine (specs.acknowledgeUpstream) or Reset to shipped (specs.delete).
   */
  upstreamChanged: boolean;
  /** ISO-8601; null for a pure shipped spec. */
  editedAt: string | null;
}

/**
 * One field's presentation, keyed in `SpecOverlay.fields` by its overlay key — the same string a
 * diagnostic's `anchor` carries, which is what makes placing an error next to its input a lookup.
 */
export interface SpecOverlayField {
  label: string;
  /**
   * Which input edits this field. Deliberately NOT a literal union: the renderer carries a
   * documented default case, so an overlay that gains a widget in a vendor sync degrades to a
   * plain input instead of failing to compile.
   */
  widget: string;
  /** An id from `groups`. */
  group?: string;
  order?: number;
  unit?: string;
  step?: number;
  help?: string;
  advanced?: boolean;
  readOnly?: boolean;
  nullable?: boolean;
  multiple?: boolean;
  /**
   * Narrows a channel picker to one kind of the channel registry (`emitter`, `response`,
   * `reward`).
   */
  channelKind?: string;
  /**
   * Present only for `enum`. Every other picker draws its options from a registry in this same
   * reply.
   */
  options?: Array<{ value: string; label: string; help?: string }>;
}

export interface SpecOverlayGroup {
  id: string;
  label: string;
  order: number;
  help?: string;
}

/**
 * task_spec.presentation.v1.json — the label/widget/group layer over the JSON Schema. Vendored
 * alongside the compiler, so the form and the validator can never describe different documents.
 */
export interface SpecOverlay {
  presentation_version: number;
  groups: SpecOverlayGroup[];
  /** Keyed by dotted document path (`contingency.outcome_map`). */
  sections: Record<string, { group: string; rows: "indexed" | "by_id" | "by_key" | "object"; gatedBy?: string }>;
  /** Keyed by overlay key. */
  fields: Record<string, SpecOverlayField>;
}

export interface SpecDiagnostic {
  /** TG###; append-only, never reused. */
  code: string;
  severity: "INFO" | "WARN" | "ERROR";
  message: string;
  /**
   * A dotted YAML path (`contingency.outcome_map.omission.strobe`), a node id (`S12`), a
   * selector, or a registry filename. Clients should not parse it — `placement` already says
   * where it lands.
   */
  location: string | null;
  /**
   * Where this diagnostic belongs on screen, computed by the one definition in the compiler
   * (taskgraph/presentation.py). `field` anchors are overlay keys, so mapping onto an input is a
   * dictionary lookup and never a parse.
   */
  placement: "field" | "row" | "section" | "node" | "document";
  /** The overlay key, section path or node id. */
  anchor: string | null;
  detail: string | null;
  /** Rule-level: what to do about it. */
  help: string | null;
  /** e.g. `D4` — a docs/decisions.md pointer. */
  decision: string | null;
}

export interface SpecGraphNode {
  index: number;
  /** The template's node id (`engage_win`); `index` formats to the listing's `S07`. */
  symbol: string;
  label: string;
  /** 1 engagement · 2 sampling · 3 response · 4 outcome. */
  band: number;
  type: "DELAY" | "WAIT_ENTRY" | "HOLD" | "WAIT_EXIT" | "PULSE" | "TERMINAL";
  /** Timing id, when duration comes from the vector. */
  durationId: string | null;
  durationMs: number | null;
  strobeName: string | null;
  strobe: number | null;
  /** An explicit `strobe: null` (D4), not an omission. */
  silentByDesign: boolean;
  /** Channel names this state watches. */
  watch: string[];
}

export interface SpecGraphEdge {
  index: number;
  src: number;
  dst: number;
  trigger: "TIMEOUT" | "ENTER" | "HELD" | "BROKEN" | "EXIT" | "DONE" | "ADVANCE" | "REPEAT";
  /** Human-readable guard, or null for the default edge. */
  guard: string | null;
  channel: string | null;
  /** `score:wrong`, `reward:@target` — the edge's side effect. */
  effect: string | null;
}

/**
 * The compiled machine graph — six node primitives, trigger-keyed edges. Deliberately NOT the
 * derived TaskGraphModel: that describes what an animal does; this describes what the interpreter
 * executes.
 */
export interface SpecGraph {
  nodes: SpecGraphNode[];
  edges: SpecGraphEdge[];
  entry: number;
}

export interface SpecTableSummary {
  specId: string;
  specHash: string;
  specVersion: number;
  vocabVersion: number;
  template: string;
  templateVersion: number;
  templateHash: string;
  nNodes: number;
  nEdges: number;
  nTiming: number;
  nTrialTypes: number;
  /** Bytes on the wire to a board — the capacity that matters. */
  sizeBytes: number;
  /** Hex, `0x`-prefixed — matches the CLI's own rendering. */
  crc32: string;
}

/**
 * A spec that doesn't compile is a SUCCESSFUL reply carrying diagnostics, never a command error —
 * same discipline as Analytics' corrupt-file rule. SPEC_INVALID is reserved for a document that
 * isn't a document.
 */
export interface SpecCompileResult {
  ok: boolean;
  diagnostics: SpecDiagnostic[];
  /**
   * Null whenever any diagnostic is an ERROR — the compiler's structural gate, mirrored onto the
   * wire. There is no code path from a failing spec to a table summary.
   */
  table: SpecTableSummary | null;
  graph: SpecGraph | null;
  /**
   * emit.listing.render verbatim — the review artifact, byte-equal to the checked-in
   * specs/<id>.table.txt when the spec is unedited.
   */
  listing: string | null;
  elapsedMs: number;
}

/**
 * What a topology produces (roadmap Phase 6): the palette's validity model. A pure function of
 * the knobs, so the form re-gates its rows the instant one moves, before any compile returns.
 */
export interface SpecCapabilities {
  outcomeClasses: string[];
  /** Ordered — the form renders timing rows in exactly this order. */
  requiredTiming: string[];
  knobs: string[];
  template: string;
  templateVersion: number;
}

export interface SpecsUpdatedData {
  specs: SpecEntry[];
}

export interface DiffLine {
  op: " " | "+" | "-";
  text: string;
}

export interface DiffHunk {
  /**
   * The listing section the hunk falls in — STATES, TIMING VECTOR, TRIAL TYPES, STAGE SCHEDULE,
   * DWELL BUDGET — so a change reads as "3 states added in the sampling band" rather than "line
   * 71 moved".
   */
  section: string;
  lines: DiffLine[];
}

/**
 * A diff of the LISTING — the checked-in review artifact — never of the YAML. The listing is what
 * a reviewer reads upstream, so it is what a topology change is reviewed against here (roadmap
 * Phase 6).
 */
export interface SpecListingDiff {
  specId: string;
  baseline: "shipped" | "saved" | "spec";
  changed: boolean;
  /**
   * Null when that side does not compile. The summaries carry the headline (26 → 29 states) and
   * the provenance strip — spec_hash and template_hash move on EVERY edit, so they are excluded
   * from the hunks and shown once here instead of topping every diff.
   */
  before: SpecTableSummary | null;
  after: SpecTableSummary | null;
  hunks: DiffHunk[];
  added: number;
  removed: number;
}

export interface SpecArtifact {
  kind: "spec" | "listing" | "lint" | "table_json" | "table_bin" | "bench";
  filename: string;
  text: string | null;
  /** Only table_bin — the packed wire bytes. */
  base64: string | null;
}

export interface BoardCapabilities {
  box: number;
  /**
   * False when the board announced no CAP line — un-migrated firmware, the legacy bare-START
   * path. Not an error; it means 'flash the interpreter sketch first' and the UI offers exactly
   * that.
   */
  present: boolean;
  /** The rate that actually answered (transport detect). */
  baud: number;
  /** Numeric CAP keys — PROTO, WIRE, MAX_NODES… */
  values: Record<string, number>;
  /** Text CAP keys — SKETCH, SPEC… */
  text: Record<string, string>;
  /** Everything the board said up to READY, verbatim. */
  banner: string[];
}

export interface UploadProgressData {
  box: number;
  /**
   * detect = finding the baud · probe = reading CAP · transfer = chunks moving · verify =
   * awaiting TABLE OK.
   */
  phase: "detect" | "probe" | "transfer" | "verify";
  /** Confirmed BY THE BOARD — counted at its ACK. */
  chunk: number | null;
  chunks: number | null;
  text: string | null;
}

export interface UploadResult {
  box: number;
  specId: string;
  specHash: string;
  nBytes: number;
  chunks: number;
  crc32: string;
  /**
   * The body digest the board echoed. CRC says the bytes arrived; the digest says they decoded
   * into the right fields — a transfer can be perfect and a decode wrong, and only this catches
   * it.
   */
  digest: string;
  seconds: number;
  /** Advisory CAP notes — a dimension the board didn't announce. */
  notes: string[];
  caps: BoardCapabilities;
}

// --- Per-command and per-event payload maps --------------------------------

/** Args each command takes; `Record<string, never>` = none. */
export interface CommandArgsMap {
  "auth": { token: string };
  "ping": Record<string, never>;
  "settings.push": { settings: EphymerisSettings };
  "sketches.refresh": Record<string, never>;
  "port.passthrough.open": { box: number; baud?: number };
  "port.passthrough.close": { box: number };
  "port.send": { box: number; text: string; lineEnding?: "none" | "lf" | "cr" | "crlf" };
  "port.flash": { box: number; sketchPath: string; suppressPassthroughResume?: boolean };
  "port.reset": { box: number };
  "port.error.ack": { box: number };
  "utility.status": Record<string, never>;
  "utility.ensure": { boxes?: number[]; force?: boolean };
  "utility.identify": { box: number; on: boolean };
  "cohorts.list": Record<string, never>;
  "cohorts.get": { id: string };
  "cohorts.create": { name: string; dataFolder?: string; animals?: Animal[]; groups?: Group[] };
  "cohorts.update": { id: string; patch: CohortPatch };
  "cohorts.archive": { id: string };
  "cohorts.restore": { id: string };
  "cohorts.delete": { id: string; confirm: boolean };
  "cohorts.setDataFolder": { id: string; path: string; moveExisting: boolean };
  "cohorts.suggestGroups": { id: string; groupCount?: number; maxGroupSize?: number; balanceBySex?: boolean };
  "prefixes.list": Record<string, never>;
  "prefixes.create": { name: string };
  "prefixes.delete": { id: string };
  "tasks.getProfile": { sketchPath: string };
  "sessions.suggestNumber": { prefixId: string };
  "sessions.create": { cohortId: string; prefixId: string; sessionNumber: string; durationMinutes?: number };
  "sessions.abandon": { sessionId: string };
  "sessions.confirmMapping": { sessionId: string; groupId: string; boxes: SessionBoxMapping[] };
  "sessions.status": { sessionId: string };
  "sessions.startAll": { sessionId: string };
  "sessions.switchGroup": { sessionId: string };
  "sessions.end": { sessionId: string };
  "sessions.active": Record<string, never>;
  "port.startSession": { box: number };
  "port.stopSession": { box: number };
  "backup.syncNow": Record<string, never>;
  "sessions.list": { cohortId: string; includeAborted?: boolean };
  "analytics.summary": { cohortId: string; sessionIds?: string[]; animalIds?: string[]; minCountedTrials?: number };
  "analytics.series": { runIds: string[]; mode?: "rolling" | "cumulative"; metricIds?: string[] };
  "analytics.rescan": { cohortId: string; adoptOrphans?: boolean };
  "analytics.recentSessions": { limit?: number };
  "sessions.recover": { cohortId: string };
  "specs.list": Record<string, never>;
  "specs.get": { specId: string };
  "specs.schema": Record<string, never>;
  "specs.compile": { text: string; specId?: string };
  "specs.capabilities": { topology: unknown };
  "specs.save": { specId: string; text: string };
  "specs.delete": { specId: string };
  "specs.acknowledgeUpstream": { specId: string };
  "specs.diff": { specId: string; text?: string; baseline?: "shipped" | "saved"; againstSpecId?: string };
  "specs.export": { specId: string; text?: string; artifacts: string[] };
  "board.capabilities": { box: number; baud?: number };
  "board.uploadTable": { box: number; specId: string; text?: string };
  "utility.benchHold": { held: boolean };
}

/** The `result` field of each command's ok-reply. */
